export function chooseModel(chapter, title) {
  const candidates = models[chapter];
  if (!candidates) throw new Error(`No discussion model for chapter ${chapter}`);
  return candidates.find(x => x.match && new RegExp(x.match, 'i').test(title)) || candidates.at(-1);
}
